 captions(text,duration=8){if(!Number.isFinite(duration)||duration<=0)throw Error('Choose a positive duration.');if(text.includes('-->')){const blocks=text.replace(/\r/g,'').replace(/^WEBVTT[^\n]*\n/,'').trim().split(/\n\s*\n/);const items=[];for(const block of blocks){const lines=block.split('\n'),i=lines.findIndex(l=>l.includes('-->'));if(i<0)continue;const [a,b]=lines[i].split('-->').map(x=>x.trim().split(/\s/)[0]);const start=M.time(a),end=M.time(b),value=lines.slice(i+1).join(' ').replace(/<[^>]*>/g,'').trim();if(end<=start)throw Error('A caption must end after it starts.');if(value)items.push({start,end,text:value});}if(!items.length)throw Error('No valid subtitle cues were found.');return items.sort((a,b)=>a.start-b.start);}const words=text.trim().split(/\s+/u).filter(Boolean);if(!words.length)throw Error('Enter a script or SRT subtitles.');const cues=[];for(let i=0;i<words.length;i+=5)cues.push({start:duration*i/words.length,end:duration*Math.min(i+5,words.length)/words.length,text:words.slice(i,i+5).join(' ')});return cues;},
