 activity(samples,rate,{threshold=-35,minSilence=.45,padding=.12}={}){if(!samples?.length||!Number.isFinite(rate)||rate<=0)throw Error('No decodable audio was found.');const frame=Math.max(1,Math.round(rate*.02)),energy=[];for(let i=0;i<samples.length;i+=frame){let sum=0,n=Math.min(frame,samples.length-i);for(let j=0;j<n;j++)sum+=samples[i+j]**2;energy.push(Math.sqrt(sum/n));}const cutoff=10**(threshold/20),dur=samples.length/rate;const active=[];let start=null;for(let i=0;i<energy.length;i++){if(energy[i]>=cutoff&&start===null)start=i*.02;if((energy[i]<cutoff||i===energy.length-1)&&start!==null){const end=energy[i]<cutoff?i*.02:dur;active.push({start,end});start=null;}}const merged=[];for(const range of active){const last=merged.at(-1);if(last&&range.start-last.end<minSilence)last.end=range.end;else merged.push({...range});}const padded=[];for(const range of merged){const next={start:Math.max(0,range.start-padding),end:Math.min(dur,range.end+padding)},last=padded.at(-1);if(last&&next.start<=last.end)last.end=Math.max(last.end,next.end);else padded.push(next);}return {energy,ranges:padded,duration:dur};},
