const field=(id,label,value='',type='text')=>`<div class="field"><label class="label" for="${id}">${label}</label><input id="${id}" class="control" type="${type}" value="${value}"></div>`;
const select=(id,label,choices)=>`<div class="field"><label class="label" for="${id}">${label}</label><select id="${id}" class="control">${choices.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div>`;
const fileInput=(id,label,accept,multiple=false)=>`<div class="field"><label class="label" for="${id}">${label}</label><input id="${id}" class="control" type="file" accept="${accept}" ${multiple?'multiple':''}></div>`;
const textArea=(id,label,value='')=>`<div class="field"><label class="label" for="${id}">${label}</label><textarea id="${id}" class="control">${value}</textarea></div>`;
