async function createTranscriber(onProgress){
 const names=['transformers.min.js','ort-wasm-simd-threaded.jsep.mjs','ort-wasm-simd-threaded.jsep.wasm','encoder_model_quantized.onnx','decoder_model_merged_quantized.onnx','config.json','generation_config.json','preprocessor_config.json','tokenizer.json','tokenizer_config.json'];const urls={};for(const name of names){urls[name]=await assetURL(name,name.endsWith('.js')||name.endsWith('.mjs')?'text/javascript':name.endsWith('.wasm')?'application/wasm':'application/octet-stream');}
 const script=`let pipelineInstance;self.onmessage=async event=>{const {type,urls,samples,language}=event.data;try{if(type==='init'){const lib=await import(urls['transformers.min.js']);const env=lib.env;env.allowRemoteModels=false;env.allowLocalModels=true;env.useBrowserCache=false;env.useFSCache=false;env.useFS=false;env.useCustomCache=true;env.customCache={match:async key=>{const file=String(key).split('/').pop();if(urls[file])return fetch(urls[file]);return undefined;},put:async()=>{}};env.backends.onnx.wasm.numThreads=1;env.backends.onnx.wasm.proxy=false;env.backends.onnx.wasm.wasmPaths={mjs:urls['ort-wasm-simd-threaded.jsep.mjs'],wasm:urls['ort-wasm-simd-threaded.jsep.wasm']};pipelineInstance=await lib.pipeline('automatic-speech-recognition','Xenova/whisper-tiny',{device:'wasm',dtype:'q8',progress_callback:p=>self.postMessage({type:'progress',progress:p.progress||0})});self.postMessage({type:'ready'});}else if(type==='transcribe'){const result=await pipelineInstance(samples,{language,task:'transcribe',return_timestamps:true,chunk_length_s:30,stride_length_s:5});self.postMessage({type:'result',result});}}catch(error){self.postMessage({type:'error',message:error.message});}};`;
 const workerURL=URL.createObjectURL(new Blob([script],{type:'text/javascript'}));const worker=new Worker(workerURL,{type:'module'});let settled=false;const ready=new Promise((resolve,reject)=>{worker.onerror=e=>reject(Error(e.message||'The local speech engine could not start.'));worker.onmessage=e=>{if(e.data.type==='ready'){settled=true;resolve();}else if(e.data.type==='error')reject(Error(e.data.message));else if(e.data.type==='progress')onProgress(e.data.progress);};});worker.postMessage({type:'init',urls});return {worker,workerURL,ready};
}
M.transcribe=async(audio,language,cancelled=()=>false)=>{let engine;const creation=createTranscriber(()=>{}).then(value=>{if(cancelled()){value.worker.terminate();URL.revokeObjectURL(value.workerURL);throw Error('Export cancelled.');}return value;});try{engine=await M.waitPromise(creation,cancelled,900000);await M.waitPromise(engine.ready,cancelled,900000);return await M.waitPromise(new Promise((resolve,reject)=>{engine.worker.onerror=event=>reject(Error(event.message||'Speech recognition failed.'));engine.worker.onmessage=event=>{if(event.data.type==='result')resolve(event.data.result);if(event.data.type==='error')reject(Error(event.data.message));};const samples=new Float32Array(audio.samples);engine.worker.postMessage({type:'transcribe',samples,language},[samples.buffer]);}),cancelled,900000);}finally{if(engine){engine.worker.terminate();URL.revokeObjectURL(engine.workerURL);}}};
M.refineHighlights=(ranges,cues,total,requested)=>ranges.map(range=>{let start=range.start,end=range.end;const first=cues.find(cue=>cue.end>start&&cue.start<end),last=[...cues].reverse().find(cue=>cue.start<end&&cue.end>start);if(first&&Math.abs(first.start-start)<3)start=Math.max(0,first.start);if(last&&Math.abs(last.end-end)<3)end=Math.min(total,last.end);if(end-start>requested*1.3)end=Math.min(total,start+requested);return {...range,start,end};}).sort((a,b)=>a.start-b.start).filter((range,i,all)=>i===0||range.start>=all[i-1].end);
EXTRA_TOOLS['add-subtitles-to-video']=()=>{
 renderBase(fileInput('subtitle-media','Choose a video or audio file','video/*,audio/*')+select('subtitle-language','Speech language',[['english','English'],['french','French'],['arabic','Arabic'],['spanish','Spanish'],['german','German']])+'<p class="subtle">The recognition model is included in this page. No recording is sent to a server.</p><div class="actionbar">'+button('subtitle-transcribe','Transcribe speech',true,'spark')+button('subtitle-stop','Cancel')+'</div><progress id="subtitle-progress" class="pdf-progress" value="0" max="100"></progress>'+textArea('subtitle-text','Editable SRT subtitles')+'<div class="actionbar">'+button('subtitle-srt','Download SRT')+button('subtitle-vtt','Download VTT')+'</div>'+dimensions()+button('subtitle-video','Export captioned video',true,'download')+output());
 let transcriber=null,cancelled=false,runToken=0;const pending=new Set();const cancellable=promise=>new Promise((resolve,reject)=>{const abort=()=>reject(Error('Transcription cancelled.'));pending.add(abort);Promise.resolve(promise).then(resolve,reject).finally(()=>pending.delete(abort));});const stop=()=>{runToken++;cancelled=true;for(const abort of pending)abort();pending.clear();transcriber?.worker.terminate();if(transcriber)URL.revokeObjectURL(transcriber.workerURL);transcriber=null;};$('subtitle-stop').onclick=()=>{stop();message('Transcription cancelled.');};window.addEventListener('pagehide',stop,{once:true});$('subtitle-media').onchange=()=>{stop();$('subtitle-text').value='';$('media-results').replaceChildren();};
 wrapButton('subtitle-transcribe',async()=>{const file=$('subtitle-media').files[0];if(!file)throw Error('Choose a video or audio file first.');cancelled=false;const attempt=++runToken;message('Preparing audio and the local speech model…');try{const audio=await cancellable(M.audio(file));if(attempt!==runToken)return;let peak=0;for(const sample of audio.samples)peak=Math.max(peak,Math.abs(sample));if(peak<.0001)throw Error('No speech was recognized. Check the language and audio.');if(!transcriber){transcriber=await cancellable(createTranscriber(progress=>$('subtitle-progress').value=progress).then(engine=>{if(attempt!==runToken){engine.worker.terminate();URL.revokeObjectURL(engine.workerURL);throw Error('Transcription cancelled.');}return engine;}));await cancellable(transcriber.ready);}if(attempt!==runToken)return;message('Transcribing on your device. This may take a while…');const result=await cancellable(new Promise((resolve,reject)=>{const worker=transcriber.worker;worker.onerror=e=>reject(Error(e.message||'Speech recognition failed.'));worker.onmessage=e=>{if(e.data.type==='result')resolve(e.data.result);if(e.data.type==='error')reject(Error(e.data.message));};worker.postMessage({type:'transcribe',samples:audio.samples,language:$('subtitle-language').value},[audio.samples.buffer]);}));if(attempt!==runToken)return;let cues=(result.chunks||[]).map((c,i,arr)=>({start:Math.max(0,c.timestamp?.[0]||0),end:Math.min(audio.duration,c.timestamp?.[1]??arr[i+1]?.timestamp?.[0]??audio.duration),text:(c.text||'').replace(/\[(?:BLANK_AUDIO|SILENCE|NO_SPEECH)\]/gi,'').trim()})).filter(c=>c.end>c.start&&c.text);const transcript=(result.text||'').replace(/\[(?:BLANK_AUDIO|SILENCE|NO_SPEECH)\]/gi,'').trim();if(!cues.length&&transcript)cues=M.captions(transcript,audio.duration);if(!cues.length)throw Error('No speech was recognized. Check the language and audio.');$('subtitle-text').value=M.srt(cues);$('subtitle-progress').value=100;message('Transcription complete. Review the words and timing.');}catch(e){if(attempt!==runToken)return;stop();throw e;}});
 $('subtitle-srt').onclick=()=>{try{const cues=M.captions($('subtitle-text').value);download(new Blob([M.srt(cues)],{type:'application/x-subrip'}),'subtitles.srt');}catch(e){message(e.message,true);}};$('subtitle-vtt').onclick=()=>{try{const cues=M.captions($('subtitle-text').value);download(new Blob([M.srt(cues,true)],{type:'text/vtt'}),'subtitles.vtt');}catch(e){message(e.message,true);}};
 wrapButton('subtitle-video',async()=>{const file=$('subtitle-media').files[0];if(!file)throw Error('Choose a video or audio file first.');const cues=M.captions($('subtitle-text').value),[width,height]=$('media-size').value.split('x').map(Number);cancelled=false;message('Exporting video in real time…');const result=await M.exportVideo({file,width,height,cancelled:()=>cancelled,progress:p=>$('subtitle-progress').value=p*100,draw:(ctx,video,t,w,h)=>{drawFit(ctx,video,w,h,'blur');const cue=cues.find(c=>t>=c.start&&t<c.end);if(cue){ctx.fillStyle='rgba(0,0,0,.72)';const size=Math.round(w*.055);ctx.font=`700 ${size}px sans-serif`;const rows=lines(ctx,cue.text,w*.86);const boxH=rows.length*size*1.3+30;ctx.fillRect(w*.04,h*.8-boxH/2,w*.92,boxH);drawText(ctx,cue.text,w/2,h*.8-boxH/2+25,w*.86,size);}}});showDownload(result.blob,'captioned-video.'+result.extension);message('Ready to download');});
};
EXTRA_TOOLS['creator-studio']=()=>{
 renderBase(fileInput('studio-media','Inspect a video or audio file','video/*,audio/*')+'<video id="media-video" class="media-preview" controls playsinline></video>'+field('studio-title','Project title','My next video')+select('studio-platform','Publishing format',[['reel','Reel / Short · 9:16'],['youtube','YouTube · 16:9'],['square','Square · 1:1']])+textArea('studio-notes','Script and project notes')+'<div class="studio-tools"><a class="btn" href="ai-clip-maker.html">AI Clip Maker</a><a class="btn" href="horizontal-to-vertical-video.html">Horizontal to Vertical Video</a><a class="btn" href="add-subtitles-to-video.html">Auto Subtitles</a><a class="btn" href="remove-silence-from-video.html">Silence Remover</a><a class="btn" href="animated-captions.html">Animated Captions</a><a class="btn" href="youtube-thumbnail-maker.html">YouTube Thumbnail Maker</a><a class="btn" href="video-templates.html">Video Templates</a><a class="btn" href="glass-slides.html">Glass Slides</a><a class="btn" href="motion-titles.html">Motion Titles</a><a class="btn" href="paper-animation.html">Paper Motion Studio</a></div><div class="options">'+check('studio-edited','Trim and frame checked')+check('studio-captions','Captions reviewed')+check('studio-rights','Media rights checked')+'</div>'+button('studio-save','Download project plan',true,'download')+output());let file=null;$('studio-media').onchange=()=>{file=$('studio-media').files[0];if(file){previewVideo(file);$('media-video').onloadedmetadata=()=>{const pre=document.createElement('pre');pre.textContent=JSON.stringify({file:file.name,bytes:file.size,durationSeconds:$('media-video').duration,width:$('media-video').videoWidth,height:$('media-video').videoHeight},null,2);$('media-results').replaceChildren(pre);};$('media-video').onerror=()=>message('This media format could not be decoded.',true);}};$('studio-save').onclick=()=>{const plan={version:1,title:$('studio-title').value,format:$('studio-platform').value,notes:$('studio-notes').value,sourceFile:file?.name||null,checks:{framing:$('studio-edited').checked,captions:$('studio-captions').checked,rights:$('studio-rights').checked}};download(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'}),'creator-project.json');};
};
